import { sql, type Kysely } from 'kysely';

/**
 * Migration 0001 (BACKLOG T006): extensions, schemas `meta`/`data`/`fx`,
 * `meta.f_unaccent`, and the first meta tables (SPEC §5.10, ADR-23).
 *
 * Conventions for every meta table:
 * - `id text` holding a public ID `<prefix>_<16 base62>` generated by the app
 *   (CONTRACTS §1.2); pure join tables use a composite primary key.
 * - `created_at`/`updated_at timestamptz NOT NULL DEFAULT now()`;
 *   `meta.set_updated_at()` refreshes `updated_at` on every UPDATE.
 *   Append-only tables (`events`, `audit_logs`) have no `updated_at`.
 * - Tenant tables carry `organization_id`, also child and join tables. Child
 *   rows reference their parent through `(organization_id, parent_id)`, so a
 *   row can never point at a parent of another organization.
 * - Membership rows cascade with their parent; rows that own content
 *   (workspaces → bases) are `RESTRICT`: deleting them is a service operation
 *   that also drops the `data.*` tables.
 *
 * This file is locked by `migrations.lock.json`: never edit it once merged.
 */

const EXTENSIONS_AND_SCHEMAS = [
  // Trusted extensions: the database owner can create them without superuser.
  'CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public',
  'CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA public',
  'CREATE EXTENSION IF NOT EXISTS unaccent WITH SCHEMA public',
  'CREATE EXTENSION IF NOT EXISTS citext WITH SCHEMA public',
  'CREATE SCHEMA IF NOT EXISTS meta',
  'CREATE SCHEMA IF NOT EXISTS data',
  'CREATE SCHEMA IF NOT EXISTS fx',
  // IMMUTABLE wrapper so unaccent can be used in indexes (SPEC §5.2).
  `CREATE OR REPLACE FUNCTION meta.f_unaccent(text) RETURNS text
   LANGUAGE sql IMMUTABLE PARALLEL SAFE STRICT
   AS $$ SELECT public.unaccent('public.unaccent'::regdictionary, $1) $$`,
  `CREATE FUNCTION meta.set_updated_at() RETURNS trigger
   LANGUAGE plpgsql
   AS $$
   BEGIN
     NEW.updated_at := now();
     RETURN NEW;
   END
   $$`,
];

