const AUDIT_GUARDS = [
  // ADR-23 §5: append-only. Only meta.audit_redact (which sets the GUC for
  // its own duration) may UPDATE; nothing may DELETE or TRUNCATE. Retention
  // drops whole partitions, which fires no row trigger. Known limit: the app
  // role can set the GUC itself, so this stops programming errors, not a
  // database user (separate roles are Phase 2).
  `CREATE FUNCTION meta.audit_logs_append_only() RETURNS trigger
   LANGUAGE plpgsql
   AS $$
   BEGIN
     IF TG_OP = 'UPDATE' AND current_setting('app.audit_redact', true) = 'on' THEN
       RETURN NEW;
     END IF;
     RAISE EXCEPTION 'meta.audit_logs is append-only: % is not allowed', TG_OP
       USING ERRCODE = 'insufficient_privilege',
             HINT = 'Use meta.audit_redact(...) to redact personal data.';
   END
   $$`,
  `CREATE TRIGGER audit_logs_append_only
     BEFORE UPDATE OR DELETE ON meta.audit_logs
     FOR EACH ROW EXECUTE FUNCTION meta.audit_logs_append_only()`,
  `CREATE TRIGGER audit_logs_no_truncate
     BEFORE TRUNCATE ON meta.audit_logs
     FOR EACH STATEMENT EXECUTE FUNCTION meta.audit_logs_append_only()`,
  // Monthly partitions of events / audit_logs: [first day of month, next
  // month) in UTC, named <table>_pYYYYMM. Idempotent; reused by the partition
  // maintenance job (T010). Statement triggers are not inherited, so each
  // audit partition gets its own TRUNCATE guard.
  `CREATE FUNCTION meta.create_monthly_partition(p_table text, p_month date) RETURNS text
   LANGUAGE plpgsql
   SET search_path = pg_catalog, pg_temp
   AS $$
   DECLARE
     v_first date := date_trunc('month', p_month::timestamp)::date;
     v_next date := (date_trunc('month', p_month::timestamp) + interval '1 month')::date;
     v_name text;
   BEGIN
     IF p_table IS NULL OR p_table NOT IN ('events', 'audit_logs') THEN
       RAISE EXCEPTION 'meta.create_monthly_partition: unsupported table %', p_table
         USING ERRCODE = 'invalid_parameter_value';
     END IF;
     IF p_month IS NULL THEN
       RAISE EXCEPTION 'meta.create_monthly_partition: month is required'
         USING ERRCODE = 'invalid_parameter_value';
     END IF;
     v_name := p_table || '_p' || to_char(v_first, 'YYYYMM');
     IF to_regclass('meta.' || quote_ident(v_name)) IS NOT NULL THEN
       RETURN v_name;
     END IF;
     EXECUTE format(
       'CREATE TABLE meta.%I PARTITION OF meta.%I FOR VALUES FROM (%L) TO (%L)',
       v_name,
       p_table,
       make_timestamptz(extract(year FROM v_first)::int, extract(month FROM v_first)::int, 1, 0, 0, 0, 'UTC'),
       make_timestamptz(extract(year FROM v_next)::int, extract(month FROM v_next)::int, 1, 0, 0, 0, 'UTC')
     );
     IF p_table = 'audit_logs' THEN
       EXECUTE format(
         'CREATE TRIGGER audit_logs_no_truncate BEFORE TRUNCATE ON meta.%I '
         'FOR EACH STATEMENT EXECUTE FUNCTION meta.audit_logs_append_only()',
         v_name
       );
     END IF;
     RETURN v_name;
   END
   $$`,
  // ADR-23 §5: redaction of personal data, requested by the org owner
  // through the API (the service checks permissions and audits the request).
  //   entity mode: p_entity_type + p_entity_ids → before/after of those
  //                entities become {"redacted": true} (NULL stays NULL);
  //   user mode:   p_user_id → ip/user_agent of the user's own actions become
  //                NULL (actor_id kept), and before/after of entries about the
  //                user entity are redacted.
  // Never touches entries whose actor is the requester, `audit.*` entries or
  // other organizations. Returns the number of rows changed.
  // The GUC is switched on only around its own UPDATEs and restored before
  // returning (a function SET clause cannot name a custom parameter when the
  // owner is not a superuser). On error the statement fails and the
  // (sub)transaction rollback restores the GUC.
  `CREATE FUNCTION meta.audit_redact(
     p_organization_id text,
     p_requested_by text,
     p_entity_type text DEFAULT NULL,
     p_entity_ids text[] DEFAULT NULL,
     p_user_id text DEFAULT NULL
   ) RETURNS bigint
   LANGUAGE plpgsql
   SET search_path = pg_catalog, pg_temp
   AS $$
   DECLARE
     v_redacted constant jsonb := '{"redacted": true}'::jsonb;
     v_previous text := coalesce(current_setting('app.audit_redact', true), '');
     v_rows bigint;
     v_total bigint := 0;
   BEGIN
     IF p_organization_id IS NULL OR p_requested_by IS NULL THEN
       RAISE EXCEPTION 'meta.audit_redact: organization and requester are required'
         USING ERRCODE = 'invalid_parameter_value';
     END IF;
     IF (p_user_id IS NULL) = (p_entity_type IS NULL) THEN
       RAISE EXCEPTION 'meta.audit_redact: pass either an entity type with ids or a user id'
         USING ERRCODE = 'invalid_parameter_value';
     END IF;
     IF p_entity_type IS NOT NULL AND (p_entity_ids IS NULL OR cardinality(p_entity_ids) = 0) THEN
       RAISE EXCEPTION 'meta.audit_redact: entity ids are required'
         USING ERRCODE = 'invalid_parameter_value';
     END IF;

     PERFORM set_config('app.audit_redact', 'on', true);

     IF p_entity_type IS NOT NULL THEN
       UPDATE meta.audit_logs
          SET before = CASE WHEN before IS NULL THEN NULL ELSE v_redacted END,
              after = CASE WHEN after IS NULL THEN NULL ELSE v_redacted END
        WHERE organization_id = p_organization_id
          AND entity_type = p_entity_type
          AND entity_id = ANY (p_entity_ids)
          AND action NOT LIKE 'audit.%'
          AND actor_id IS DISTINCT FROM p_requested_by;
       GET DIAGNOSTICS v_rows = ROW_COUNT;
       v_total := v_rows;
     ELSE
       UPDATE meta.audit_logs
          SET ip = NULL,
              user_agent = NULL
        WHERE organization_id = p_organization_id
          AND actor_type = 'user'
          AND actor_id = p_user_id
          AND action NOT LIKE 'audit.%'
          AND actor_id IS DISTINCT FROM p_requested_by;
       GET DIAGNOSTICS v_rows = ROW_COUNT;
       v_total := v_rows;

       UPDATE meta.audit_logs
          SET before = CASE WHEN before IS NULL THEN NULL ELSE v_redacted END,
              after = CASE WHEN after IS NULL THEN NULL ELSE v_redacted END
        WHERE organization_id = p_organization_id
          AND entity_type = 'user'
          AND entity_id = p_user_id
          AND action NOT LIKE 'audit.%'
          AND actor_id IS DISTINCT FROM p_requested_by;
       GET DIAGNOSTICS v_rows = ROW_COUNT;
       v_total := v_total + v_rows;
     END IF;

     PERFORM set_config('app.audit_redact', v_previous, true);
     RETURN v_total;
   END
   $$`,
];

/** Tables with `updated_at`, refreshed by `meta.set_updated_at()`. */
const TABLES_WITH_UPDATED_AT = [
  'organizations',
  'users',
  'user_identities',
  'sessions',
  'password_resets',
  'org_members',
  'groups',
  'group_members',
  'workspaces',
  'workspace_members',
  'invitations',
  'bases',
  'base_roles',
  'base_role_members',
  'jobs',
  'idempotency_keys',
];

const UPDATED_AT_TRIGGERS = TABLES_WITH_UPDATED_AT.map(
  (table) =>
    `CREATE TRIGGER ${table}_set_updated_at BEFORE UPDATE ON meta.${table}
     FOR EACH ROW EXECUTE FUNCTION meta.set_updated_at()`,
);

// Current and next month (UTC); later months come from the maintenance job.
const INITIAL_PARTITIONS = [
  `SELECT meta.create_monthly_partition(t.name, (date_trunc('month', now() AT TIME ZONE 'UTC') + m.offset_months * interval '1 month')::date)
     FROM (VALUES ('events'), ('audit_logs')) AS t(name)
    CROSS JOIN (VALUES (0), (1)) AS m(offset_months)`,
];

export async function up(db: Kysely<unknown>): Promise<void> {
  const statements = [
    ...EXTENSIONS_AND_SCHEMAS,
    ...GLOBAL_TABLES,
    ...ORGANIZATION_TABLES,
    ...BASE_TABLES,
    ...OPERATIONAL_TABLES,
    ...PARTITIONED_TABLES,
    ...AUDIT_GUARDS,
    ...UPDATED_AT_TRIGGERS,
    ...INITIAL_PARTITIONS,
  ];
  // Static DDL only: no value in these statements comes from input.
  for (const statement of statements) {
    await sql.raw(statement).execute(db);
  }
}
